GPIO.setup(17, GPIO.OUT)

def turn_on():
    GPIO.output(17, GPIO.HIGH)

def turn_off():
    GPIO.output(17, GPIO.LOW)

try:
    while True:
        turn_on()
        time.sleep(2)
        turn_off()
        time.sleep(2)
except KeyboardInterrupt:
    GPIO.cleanup()

